precision mediump float;
uniform sampler2D u_texture;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_grain_size, u_grain_amount;
uniform int u_grain_type;
uniform bool u_color_grain;
varying vec2 v_texCoord;

float random(vec2 st) {
  return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

vec3 generateGrain(vec2 coord, float time) {
  vec2 grainCoord = coord * u_resolution * u_grain_size;

  float grain1 = (random(grainCoord + time) - 0.5) * 2.0;
  float grain2 = (random(grainCoord + time + 123.456) - 0.5) * 2.0;
  float grain3 = (random(grainCoord + time + 456.789) - 0.5) * 2.0;

  if (u_color_grain) {
    return vec3(grain1, grain2, grain3) * u_grain_amount;
  } else {
    return vec3(grain1) * u_grain_amount;
  }
}

void main() {
  vec4 color = texture2D(u_texture, v_texCoord);

  vec3 grain = generateGrain(v_texCoord, u_time);

  // Adjust grain intensity based on luminance (darker areas get more grain)
  float luminance = dot(color.rgb, vec3(0.299, 0.587, 0.114));
  float grainMultiplier = mix(1.5, 0.5, luminance);

  color.rgb += grain * grainMultiplier;

  gl_FragColor = vec4(clamp(color.rgb, 0.0, 1.0), color.a);
}

precision mediump float;
uniform sampler2D u_texture;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_tape_noise, u_tracking_lines, u_color_bleeding, u_jitter;
varying vec2 v_texCoord;

float random(vec2 st) {
  return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

void main() {
  vec2 uv = v_texCoord;

  // Jitter effect
  float jitterOffset = (random(vec2(floor(u_time * 60.0))) - 0.5) * u_jitter * 0.01;
  uv.x += jitterOffset;

  // Color bleeding (horizontal blur)
  vec4 color = texture2D(u_texture, uv);
  if (u_color_bleeding > 0.0) {
    vec2 texelSize = 1.0 / u_resolution;
    vec4 bleed = vec4(0.0);
    for (float i = -2.0; i <= 2.0; i += 1.0) {
      bleed += texture2D(u_texture, uv + vec2(i * texelSize.x * u_color_bleeding * 3.0, 0.0));
    }
    bleed /= 5.0;
    color = mix(color, bleed, u_color_bleeding * 0.5);
  }

  // Tracking lines
  float trackingLine = sin(uv.y * u_resolution.y * 0.5 + u_time * 10.0);
  trackingLine = smoothstep(0.8, 1.0, trackingLine);
  color.rgb = mix(color.rgb, color.rgb * 0.5, trackingLine * u_tracking_lines);

  // Tape noise
  float noise = (random(uv + u_time) - 0.5) * u_tape_noise * 0.3;
  color.rgb += noise;

  // VHS color characteristics
  color.r *= 1.1;
  color.g *= 0.95;
  color.b *= 0.9;

  gl_FragColor = vec4(clamp(color.rgb, 0.0, 1.0), color.a);
}

precision mediump float;
uniform sampler2D u_texture;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_noise_intensity, u_block_size, u_compression_artifacts;
varying vec2 v_texCoord;

float random(vec2 st) {
  return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

void main() {
  vec2 uv = v_texCoord;

  // Block-based compression artifacts
  if (u_compression_artifacts > 0.0) {
    vec2 blockSize = vec2(u_block_size) / u_resolution;
    vec2 blockUV = floor(uv / blockSize) * blockSize;

    // Sample from block center
    vec4 blockColor = texture2D(u_texture, blockUV + blockSize * 0.5);
    vec4 originalColor = texture2D(u_texture, uv);

    uv = mix(uv, blockUV + blockSize * 0.5, u_compression_artifacts * 0.5);
  }

  vec4 color = texture2D(u_texture, uv);

  // Digital noise (random pixels)
  float pixelNoise = random(floor(uv * u_resolution) + u_time);
  if (pixelNoise > (1.0 - u_noise_intensity * 0.1)) {
    color.rgb = vec3(random(uv + u_time));
  }

  // Quantization noise
  if (u_noise_intensity > 0.0) {
    float levels = mix(256.0, 16.0, u_noise_intensity);
    color.rgb = floor(color.rgb * levels) / levels;
  }

  gl_FragColor = color;
}

precision mediump float;
uniform sampler2D u_texture;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_static_amount, u_interference_frequency, u_signal_loss;
varying vec2 v_texCoord;

float random(vec2 st) {
  return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

void main() {
  vec2 uv = v_texCoord;
  vec4 color = texture2D(u_texture, uv);

  // Static noise
  float staticNoise = random(uv + u_time);
  vec3 staticColor = vec3(staticNoise);

  // Interference bands
  float interference = sin(uv.y * u_interference_frequency + u_time * 5.0);
  interference = smoothstep(0.7, 1.0, interference);

  // Mix static with original image
  color.rgb = mix(color.rgb, staticColor, u_static_amount * staticNoise);

  // Apply interference
  color.rgb = mix(color.rgb, staticColor * 0.5, interference * u_static_amount);

  // Signal loss (random blackouts)
  float signalLoss = random(vec2(floor(u_time * 10.0)));
  if (signalLoss < u_signal_loss) {
    color.rgb *= 0.1;
  }

  gl_FragColor = color;
}
